-- Every table of docs/spec.md section 7. IDs are generated by the application (UUIDv7); the
-- defaults are for manual inserts (e.g. the backup script recording a run).

CREATE TABLE products (
    id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    -- carried in tokens as their audience; immutable once the product has licences (trigger below)
    code             TEXT NOT NULL UNIQUE CHECK (code ~ '^[a-z0-9][a-z0-9-]{0,62}$'),
    name             TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    description      TEXT CHECK (length(description) <= 2000),
    message_template TEXT NOT NULL DEFAULT '' CHECK (length(message_template) <= 10000),
    is_active        BOOLEAN NOT NULL DEFAULT TRUE,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE customers (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name       TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    email      TEXT CHECK (length(email) BETWEEN 3 AND 320),
    notes      TEXT CHECK (length(notes) <= 2000),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX customers_email_unique ON customers (lower(email)) WHERE email IS NOT NULL;

CREATE TABLE licenses (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    product_id        UUID NOT NULL REFERENCES products (id) ON DELETE RESTRICT,
    -- deleting a customer erases their personal data; their licences keep working
    customer_id       UUID REFERENCES customers (id) ON DELETE SET NULL,
    key_lookup        BYTEA NOT NULL UNIQUE CHECK (length(key_lookup) = 32),
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at        TIMESTAMPTZ,
    revoked_at        TIMESTAMPTZ,
    revocation_reason TEXT CHECK (length(revocation_reason) <= 500),
    internal_notes    TEXT CHECK (length(internal_notes) <= 2000),
    CHECK (revocation_reason IS NULL OR revoked_at IS NOT NULL)
);
CREATE INDEX licenses_product ON licenses (product_id);
CREATE INDEX licenses_customer ON licenses (customer_id);
CREATE INDEX licenses_expires_at ON licenses (expires_at) WHERE expires_at IS NOT NULL;

-- the encrypted key; deleted when the licence is revoked
CREATE TABLE license_key_secrets (
    license_id         UUID PRIMARY KEY REFERENCES licenses (id) ON DELETE CASCADE,
    ciphertext         BYTEA NOT NULL,
    nonce              BYTEA NOT NULL CHECK (length(nonce) = 24),
    encryption_version SMALLINT NOT NULL CHECK (encryption_version > 0)
);

CREATE TABLE activations (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    license_id              UUID NOT NULL REFERENCES licenses (id) ON DELETE RESTRICT,
    device_public_key       BYTEA NOT NULL CHECK (length(device_public_key) = 32),
    device_fingerprint_hash BYTEA CHECK (length(device_fingerprint_hash) = 32),
    device_name             TEXT NOT NULL CHECK (length(device_name) BETWEEN 1 AND 200),
    platform                TEXT NOT NULL CHECK (length(platform) BETWEEN 1 AND 200),
    -- the version reported at the latest activation or check
    app_version             TEXT NOT NULL CHECK (length(app_version) BETWEEN 1 AND 200),
    activated_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_checked_at         TIMESTAMPTZ,
    revoked_at              TIMESTAMPTZ,
    revocation_reason       TEXT CHECK (revocation_reason IN ('reset', 'licence_revoked')),
    CHECK ((revoked_at IS NULL) = (revocation_reason IS NULL))
);
-- at most one active computer per licence; revoked activations stay as history
CREATE UNIQUE INDEX activations_one_active_per_license ON activations (license_id) WHERE revoked_at IS NULL;

CREATE TABLE verification_challenges (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    activation_id UUID NOT NULL REFERENCES activations (id) ON DELETE CASCADE,
    nonce_hash    BYTEA NOT NULL CHECK (length(nonce_hash) = 32),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at    TIMESTAMPTZ NOT NULL,
    consumed_at   TIMESTAMPTZ
);
CREATE INDEX verification_challenges_activation ON verification_challenges (activation_id);
CREATE INDEX verification_challenges_expires_at ON verification_challenges (expires_at);

CREATE TABLE admin_users (
    id                     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    username               TEXT NOT NULL CHECK (username ~ '^[a-z0-9][a-z0-9._-]{0,62}$'),
    password_hash          TEXT NOT NULL,
    totp_secret_ciphertext BYTEA NOT NULL,
    totp_secret_nonce      BYTEA NOT NULL CHECK (length(totp_secret_nonce) = 24),
    totp_last_used_step    BIGINT,
    created_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_login_at          TIMESTAMPTZ,
    disabled_at            TIMESTAMPTZ
);
CREATE UNIQUE INDEX admin_users_username_unique ON admin_users (lower(username));

CREATE TABLE admin_recovery_codes (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    admin_user_id UUID NOT NULL REFERENCES admin_users (id) ON DELETE CASCADE,
    code_hash     BYTEA NOT NULL UNIQUE CHECK (length(code_hash) = 32),
    used_at       TIMESTAMPTZ
);
CREATE INDEX admin_recovery_codes_admin ON admin_recovery_codes (admin_user_id);

CREATE TABLE admin_sessions (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    admin_user_id UUID NOT NULL REFERENCES admin_users (id) ON DELETE CASCADE,
    token_hash    BYTEA NOT NULL UNIQUE CHECK (length(token_hash) = 32),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_seen_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at    TIMESTAMPTZ NOT NULL,
    revoked_at    TIMESTAMPTZ
);
CREATE INDEX admin_sessions_admin ON admin_sessions (admin_user_id);
CREATE INDEX admin_sessions_expires_at ON admin_sessions (expires_at);

CREATE TABLE admin_preferences (
    admin_user_id UUID PRIMARY KEY REFERENCES admin_users (id) ON DELETE CASCADE,
    preferences   JSONB NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(preferences) = 'object'),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE audit_logs (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    admin_user_id UUID REFERENCES admin_users (id) ON DELETE SET NULL,
    action        TEXT NOT NULL CHECK (length(action) BETWEEN 1 AND 100),
    entity_type   TEXT NOT NULL CHECK (length(entity_type) BETWEEN 1 AND 100),
    entity_id     UUID,
    metadata      JSONB NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(metadata) = 'object'),
    ip_address    INET,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX audit_logs_created_at ON audit_logs (created_at);
CREATE INDEX audit_logs_entity ON audit_logs (entity_type, entity_id);
CREATE INDEX audit_logs_admin ON audit_logs (admin_user_id);

CREATE TABLE backup_runs (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    finished_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    archive_name TEXT NOT NULL CHECK (length(archive_name) BETWEEN 1 AND 255),
    size_bytes   BIGINT NOT NULL CHECK (size_bytes >= 0)
);
CREATE INDEX backup_runs_finished_at ON backup_runs (finished_at);

-- A licence's state is derived, never stored (docs/design-decisions.md).
CREATE VIEW license_states AS
SELECT l.id AS license_id,
       CASE
           WHEN l.revoked_at IS NOT NULL THEN 'revoked'
           WHEN a.id IS NOT NULL THEN 'redeemed'
           ELSE 'unused'
       END AS state,
       a.id AS active_activation_id,
       a.activated_at AS redeemed_at
FROM licenses l
LEFT JOIN activations a ON a.license_id = l.id AND a.revoked_at IS NULL;

-- Tokens carry the product code as their audience, so changing it would invalidate every
-- application already activated for that product.
CREATE FUNCTION products_code_is_immutable_with_licenses() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.code <> OLD.code AND EXISTS (SELECT 1 FROM licenses WHERE product_id = OLD.id) THEN
        RAISE EXCEPTION 'product code cannot change once the product has licences'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER products_code_immutable
BEFORE UPDATE OF code ON products
FOR EACH ROW EXECUTE FUNCTION products_code_is_immutable_with_licenses();
